export class Plans {
  private readonly session = inject(Session);
  private readonly service = inject(PlansService);

  readonly personId = input.required<number>();
  readonly personName = input.required<string>();
  readonly plans = input<Plan[]>([]);
  readonly added = output<Plan>();

  protected readonly amount = signal('');
  protected readonly start = signal('');
  protected readonly every = signal('');
  protected readonly day = signal('');
  protected readonly end = signal('');
  protected readonly error = signal<string | null>(null);
  private saving = false;

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  protected async submit(event: Event): Promise<void> {
    event.preventDefault();
    if (this.saving) return;
    this.error.set(null);
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const fields = { amount: this.amount().trim(), start: this.start().trim(), every: this.every().trim(), day: this.day().trim(), end: this.end().trim() };
    if (!AMOUNT.test(fields.amount) || Number(fields.amount) <= 0) {
      this.error.set('Type an amount above zero with up to two decimals.');
      return;
    }
    if ((fields.every === '') === (fields.day === '')) {
      this.error.set('Give either every N days or a day of the month.');
      return;
    }
    if (fields.every !== '' && (!EVERY.test(fields.every) || Number(fields.every) < 1)) {
      this.error.set('Every must be a whole number of days, at least 1.');
      return;
    }
    if (fields.day !== '' && (!DAY.test(fields.day) || Number(fields.day) < 1 || Number(fields.day) > 31)) {
      this.error.set('The day of the month must be a whole number from 1 to 31.');
      return;
    }
    if (!DATE.test(fields.start) || !DATE.test(fields.end)) {
      this.error.set('Type the start and end as YYYY-MM-DD.');
      return;
    }
    if (fields.end < fields.start) {
      this.error.set('The end cannot be before the start.');
      return;
    }
    this.saving = true;
    try {
      const plan = await this.service.add(sheet, this.personId(), fields);
      if (this.session.sheetId() !== sheet) return;
      this.amount.set('');
      this.start.set('');
      this.every.set('');
      this.day.set('');
      this.end.set('');
      this.added.emit(plan);
    } catch {
      if (this.session.sheetId() !== sheet) return;
      this.error.set('That plan could not be added.');
    } finally {
      this.saving = false;
    }
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { Claim } from './claims.service';

/** A person's plan: a claim of `amount` on every plan date (the start, then every `every` days; or,
 *  monthly, `day` of every month from the start's month, the month's last day when it is shorter, those
 *  before the start left out) up to the end, and how many claims it has made so far. */
export interface Plan {
  id: number;
  personId: number;
  amount: string;
  start: string;
  every: number | null;
  day: number | null;
  end: string;
  generated: number;
}

/** A plan asked: amount, start and end as typed, and either the interval in whole days or the day of
 *  the month (the other blank). */
export interface PlanFields {
  amount: string;
  start: string;
  every: string;
  day: string;
  end: string;
}

/** How a generate went: how many claims it made, the claims, and every plan as it stands after. */
export interface Generated {
  made: number;
  claims: Claim[];
  plans: Plan[];
}

// The plans on a sheet, read from and written to the server.
@Injectable({ providedIn: 'root' })
export class PlansService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(sheet: string): Promise<Plan[]> {
    return firstValueFrom(this.http.get<Plan[]>(this.url(sheet), { headers: this.session.headers() }));
  }

  /** Add a plan for the person. Refused (400, 422) when the amount, interval or day is bad,
   *  both or neither of interval and day are given, or the end is
   *  before the start. */
  add(sheet: string, personId: number, fields: PlanFields): Promise<Plan> {
    return firstValueFrom(
      this.http.post<Plan>(this.url(sheet), { personId, ...fields }, { headers: this.session.headers() }),
    );
  }

  /** Make the DRAFT claims every plan on the sheet is due up to its end and the sheet's today. */
  generate(sheet: string): Promise<Generated> {
    return firstValueFrom(
      this.http.post<Generated>(`${this.url(sheet)}/generate`, null, { headers: this.session.headers() }),
    );
  }

  private url(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}/plans`;
  }
}

